insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-12', 'k-central', 3, 'أي مقاييس النزعة المركزية أنسب لتمثيل هذه القيم: 3، 5، 4، 6، 5، 40؟', '["المتوسط الحسابي","الوسيط","المنوال","المدى"]'::jsonb, 1, 'وجود قيمة متطرفة (40) يجعل المتوسط مضللاً، والوسيط لا يتأثر بالقيم الشاذة فهو الأنسب.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
