insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('kc-16', 'k-central', 2, 'أي مقاييس التشتت الآتية لا يتأثر بالقيم المتطرفة؟', '["المدى","المدى الربيعي","الانحراف المتوسط","التباين"]'::jsonb, 1, 'المدى الربيعي يعتمد على الربيعين الأعلى والأدنى ويستبعد طرفي التوزيع، فلا يتأثر بالشواذ.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
