insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lt-13', 'l-tarqeem', 2, '«يا طلابَ العلمِ ___ اجتهدوا في دروسكم». العلامة المناسبة في الفراغ:', '["الفاصلة (،)","النقطة (.)","علامة الاستفهام (؟)","الشرطتان"]'::jsonb, 0, 'توضع الفاصلة بعد المنادى فاصلةً بينه وبين جملة الطلب التي تليه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lt-14', 'l-tarqeem', 2, '«وا حسرتاه على ضياع الوقت ___». العلامة المناسبة:', '["؟","!","؛",":"]'::jsonb, 1, 'أسلوب ندبة وتحسّر، وتُختم جمل الانفعال والتأثر بعلامة التعجب (!).') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lr-13', 'l-reading', 2, 'نص يشرح خطوات إجراء تجربة علمية بالترتيب مستخدماً أفعال الأمر. نمطه:', '["سردي","إرشادي (توجيهي)","حجاجي","وصفي"]'::jsonb, 1, 'النمط الإرشادي يقدم تعليمات وخطوات تنفيذية متسلسلة بصيغة الأمر أو المصدر.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lr-14', 'l-reading', 2, 'أي العبارات الآتية حقيقة؟', '["الشتاء أجمل الفصول","تدور الأرض حول الشمس","القراءة أفضل من مشاهدة التلفاز","ينبغي على الجميع ممارسة الرياضة"]'::jsonb, 1, 'دوران الأرض حول الشمس حقيقة علمية قابلة للتحقق، أما البقية فأحكام قيمية أو توجيهات تحتمل الاختلاف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lr-15', 'l-reading', 3, 'عند قراءة نص وسؤال الطالب: «ماذا كان سيحدث لو تصرف البطل بطريقة أخرى؟» فإن المعلم ينمي مستوى الفهم:', '["الحرفي","الاستنتاجي/الإبداعي","المسحي","الآلي"]'::jsonb, 1, 'أسئلة الافتراض والتوليد تتجاوز النص المكتوب إلى التخيل والاستنتاج، وهي من مستويات الفهم العليا.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lr-16', 'l-reading', 2, '«غير أنّ» و«في المقابل» و«لذلك» تُعد من:', '["أدوات الربط التي تحقق اتساق النص","علامات الترقيم","الأساليب الإنشائية","المحسنات البديعية"]'::jsonb, 0, 'هذه روابط تبيّن العلاقات المنطقية بين الجمل (استدراك، مقابلة، نتيجة) فتحقق ترابط النص.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lr-17', 'l-reading', 3, 'طالب يقرأ النص ثم يتوقف ليسأل نفسه: «هل فهمت ما قرأت؟ وما الفكرة الأساسية؟». هذه المهارة تسمى:', '["مراقبة الفهم (ما وراء المعرفة)","القراءة الجهرية","التسميع","المسح السريع"]'::jsonb, 0, 'مراقبة الفهم أثناء القراءة من مهارات ما وراء المعرفة وتميّز القارئ الماهر عن الضعيف.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lw-11', 'l-writing', 2, 'عند كتابة تقرير عن نشاط مدرسي، أي العناصر الآتية لا يُعد من عناصره الأساسية؟', '["الهدف من النشاط","الإجراءات والبيانات","المشاعر الشخصية للكاتب ومبالغاته","النتائج والتوصيات"]'::jsonb, 2, 'التقرير يقوم على الموضوعية والحياد، والانطباعات الشخصية والمبالغات تخل بمصداقيته.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lw-12', 'l-writing', 3, '«حضر الطلاب جميعهم كلهم بأكملهم إلى الحفل». العيب الأسلوبي:', '["خطأ إملائي","حشو وإطناب ممل","خطأ نحوي","خطأ في الترقيم"]'::jsonb, 1, 'اجتمعت ثلاثة ألفاظ بمعنى التوكيد نفسه؛ والإيجاز يقتضي الاكتفاء بواحد: «حضر الطلاب جميعهم».') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lw-13', 'l-writing', 2, 'أفضل خاتمة لمقال يعالج ظاهرة تربوية:', '["تكرار المقدمة حرفياً","إجمال أبرز النتائج مع توصية عملية","طرح موضوع جديد تماماً","سرد قصة طويلة"]'::jsonb, 1, 'الخاتمة الجيدة تجمل ما سبق وتفتح أفقاً عملياً، ولا تكرر المقدمة ولا تفتح موضوعاً جديداً.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
