insert into public.pl_questions (id, topic_slug, difficulty, stem, options, answer, explanation) values ('lv-15', 'l-vocab', 2, 'معنى «يستشرف المستقبل» في جملة «يستشرف المعلم مستقبل طلابه»:', '["يتجاهله","يتطلع إليه ويستطلعه","يخاف منه","يؤجله"]'::jsonb, 1, 'استشرف الشيء أي تطلع إليه ونظر إلى ما هو آتٍ منه.') on conflict (id) do update set topic_slug = excluded.topic_slug, difficulty = excluded.difficulty, stem = excluded.stem, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
